// ─── File: src/test/java/com/bank/sealed/SealedClassTest.java ───
package com.bank.sealed;

import com.bank.sealed.channel.*;
import com.bank.sealed.result.TransactionResult;
import com.bank.sealed.service.PaymentRouter;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class SealedClassTest {

    PaymentRouter router = new PaymentRouter();

    @Test
    void exhaustiveSwitch_allChannelsHandled() {
        assertThat(router.describeChannel(new NeftChannel())).contains("NEFT");
        assertThat(router.describeChannel(new UpiChannel())).contains("UPI");
        assertThat(router.describeChannel(new RtgsChannel())).contains("RTGS");
        // All 3 handled. No default. Compiler guarantees exhaustiveness.
    }

    @Test
    void sealedPreventsUnauthorizedImplementation() {
        // public class BitcoinChannel implements PaymentChannel { }
        // → COMPILE ERROR: "BitcoinChannel is not allowed in the sealed hierarchy"
        // Only NeftChannel, UpiChannel, RtgsChannel are permitted!
        assertThat(PaymentChannel.class.isSealed()).isTrue();
        assertThat(PaymentChannel.class.getPermittedSubclasses()).hasSize(3);
    }

    @Test
    void permittedSubtypesAreFinal() {
        assertThat(NeftChannel.class.getModifiers() & java.lang.reflect.Modifier.FINAL).isNotZero();
        assertThat(UpiChannel.class.getModifiers() & java.lang.reflect.Modifier.FINAL).isNotZero();
        assertThat(RtgsChannel.class.getModifiers() & java.lang.reflect.Modifier.FINAL).isNotZero();
        // All final — no further extension allowed.
    }

    @Test
    void sealedRecords_exhaustiveResultHandling() {
        TransactionResult success = new TransactionResult.Success("UTR-123", new BigDecimal("50000"));
        TransactionResult failure = new TransactionResult.Failure("LIMIT", "Exceeded");
        TransactionResult pending = new TransactionResult.Pending("REF-456");

        assertThat(router.handleResult(success)).contains("(Recommended) ").contains("UTR-123");
        assertThat(router.handleResult(failure)).contains("(Avoid) ").contains("LIMIT");
        assertThat(router.handleResult(pending)).contains("⏳").contains("REF-456");
    }

    @Test
    void routeWithLimitCheck() {
        TransactionResult result = router.route(new UpiChannel(), "SAV2001", "CUR3001",
            new BigDecimal("200000"));  // 200K > UPI limit 100K
        assertThat(result).isInstanceOf(TransactionResult.Failure.class);
        assertThat(router.handleResult(result)).contains("LIMIT_EXCEEDED");
    }

    @Test
    void routeSuccess() {
        TransactionResult result = router.route(new NeftChannel(), "SAV2001", "CUR3001",
            new BigDecimal("500000"));
        assertThat(result).isInstanceOf(TransactionResult.Success.class);
        assertThat(router.handleResult(result)).contains("(Recommended) ");
    }
}
